   "notes": "FINAL IDENTIFIED 2 Oct 2026, from evidence rather than from the version number alone. Modification times order the whole set: v1/v2 at 17:45 on 18 Jul, v3/v4 at 17:58, the two 39-second cuts at 18:16 which were then moved to _superseded, v6 at 18:50, v7 at 20:00, v5 at 20:05 — and then, after an overnight gap, the two v8 files at 11:12 and 11:13 on 19 Jul. They are the last artefacts made. Sampling seven frames across both v8s gives a Hamming distance of 0 at every point, so they are the same edit and audio is the only difference; the silent one was written one minute LAST, which is the export made to publish from. A Goa workshop recap reel was then posted on 24 Jul 2026 — \"They walked in with questions and left with greater financial confidence\" — taking 1,291 views and 34 likes, the most-viewed of the three IFM reels that week: https://www.instagram.com/investingformummies/reel/DbMzOEgST3y/ . NOT PROVEN: no file id ties that post to v8 specifically, so the link between this master and that post is inference from the timeline, not a record. Everything else above is measured. Previously this row opened the folder because no final had been recorded.",
